<script>
document.addEventListener('DOMContentLoaded',()=>{let active=null;const close=()=>{if(!active)return;active.menu.classList.remove('show');active.toggle.setAttribute('aria-expanded','false');active=null};const place=()=>{if(!active)return;const r=active.toggle.getBoundingClientRect(),m=active.menu;m.style.visibility='hidden';m.style.left='0px';m.style.top='0px';const b=m.getBoundingClientRect();m.style.left=`${Math.max(8,Math.min(innerWidth-b.width-8,r.right-b.width))}px`;const y=r.bottom+6;m.style.top=`${y+b.height<innerHeight-8?y:Math.max(8,r.top-b.height-6)}px`;m.style.visibility='visible'};document.addEventListener('click',e=>{const t=e.target.closest('[data-overtime-action-toggle]');if(t){e.preventDefault();if(active?.toggle===t)return close();close();const menu=document.getElementById(t.dataset.menuId);if(!menu)return;document.body.append(menu);menu.classList.add('show');t.setAttribute('aria-expanded','true');active={toggle:t,menu};place();return}if(active?.menu.contains(e.target)){if(e.target.closest('a'))close();return}close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});window.addEventListener('resize',place);window.addEventListener('scroll',place,true)});
</script>
